class SamePlaceModule(dspy.Module):
    def __init__(self):
        super().__init__()
        self.predict = dspy.Predict(dspy.Signature(
            'input_name: str, input_address: str, match_name: str, match_address: str, distance: float -> is_same: bool',
            "Decide whether two business listings refer to the same physical place.\n\n"
            "You compare place A (input_name / input_address) with place B (match_name /\n"
            "match_address), plus the geographic distance between them.\n\n"
            "Only ambiguous cases reach the LLM — deterministic Python has already handled the clear ones."
        ))

    def forward(self, **inputs):
        import re

        def normalize(s):
            s = (s or "").lower()
            s = re.sub(r"[^a-z0-9]+", " ", s)
            return " ".join(s.split()).strip()

        STOPWORDS = {
            "the", "a", "an", "and", "of", "at", "in", "on",
            "restaurant", "restaurants", "cafe", "coffee", "shop", "store",
            "market", "supermarket", "grocery", "food", "foods", "cuisine",
            "kitchen", "bar", "grill", "grille", "bakery", "deli", "pizzeria",
            "pizza", "diner", "bistro", "eatery", "house", "hut", "place",
            "co", "company", "corp", "corporation", "inc", "incorporated",
            "llc", "ltd", "limited", "llp", "lp",
            "chinese", "mexican", "italian", "japanese", "thai", "indian",
            "american", "korean", "vietnamese", "french", "mediterranean",
            "asian", "european", "greek",
        }

        ADDR_SYNONYMS = {
            "street": "st", "st": "st",
            "avenue": "ave", "ave": "ave", "av": "ave",
            "boulevard": "blvd", "blvd": "blvd",
            "road": "rd", "rd": "rd",
            "drive": "dr", "dr": "dr",
            "lane": "ln", "ln": "ln",
            "court": "ct", "ct": "ct",
            "place": "pl", "pl": "pl",
            "square": "sq", "sq": "sq",
            "highway": "hwy", "hwy": "hwy",
            "parkway": "pkwy", "pkwy": "pkwy",
            "circle": "cir", "cir": "cir",
            "terrace": "ter", "ter": "ter",
            "way": "way",
            "north": "n", "n": "n",
            "south": "s", "s": "s",
            "east": "e", "e": "e",
            "west": "w", "w": "w",
            "northeast": "ne", "ne": "ne",
            "northwest": "nw", "nw": "nw",
            "southeast": "se", "se": "se",
            "southwest": "sw", "sw": "sw",
            "suite": "ste", "ste": "ste",
            "apartment": "apt", "apt": "apt",
            "number": "", "no": "",
        }

        # Strip trailing store-number tokens like "#72", "#130", "store 123", "section 149"
        NUMBERED_UNIT_WORDS = {"section", "store", "unit", "no", "number", "suite", "ste", "apt", "apartment"}

        def strip_store_number(name):
            # remove patterns like "#72" or trailing "section 149"
            n = re.sub(r"#\s*\d+", " ", name or "", flags=re.IGNORECASE)
            return n

        def normalize_address(s):
            n = normalize(s)
            tokens = [ADDR_SYNONYMS.get(t, t) for t in n.split()]
            tokens = [t for t in tokens if t]
            return " ".join(tokens)

        def normalize_name(s):
            s = strip_store_number(s)
            n = normalize(s)
            toks = n.split()
            # Drop trailing "<unitword> <number>" or "<number>" sequences at end
            for _ in range(5):
                if len(toks) >= 2 and toks[-1].isdigit() and toks[-2] in NUMBERED_UNIT_WORDS:
                    toks = toks[:-2]
                elif toks and toks[-1].isdigit():
                    toks = toks[:-1]
                else:
                    break
            tokens = [t for t in toks if t not in STOPWORDS]
            if not tokens:
                tokens = toks
            return " ".join(tokens)

        def token_set(s):
            return set(s.split()) if s else set()

        def jaccard(a, b):
            if not a and not b:
                return 1.0
            if not a or not b:
                return 0.0
            return len(a & b) / len(a | b)

        def levenshtein(a, b):
            if a == b:
                return 0
            if not a:
                return len(b)
            if not b:
                return len(a)
            if len(a) < len(b):
                a, b = b, a
            prev = list(range(len(b) + 1))
            for i, ca in enumerate(a, 1):
                cur = [i]
                for j, cb in enumerate(b, 1):
                    ins = cur[j - 1] + 1
                    dele = prev[j] + 1
                    sub = prev[j - 1] + (0 if ca == cb else 1)
                    cur.append(min(ins, dele, sub))
                prev = cur
            return prev[-1]

        def ratio(a, b):
            if not a and not b:
                return 1.0
            if not a or not b:
                return 0.0
            d = levenshtein(a, b)
            return 1.0 - d / max(len(a), len(b))

        def extract_house_number(addr):
            n = normalize_address(addr)
            m = re.match(r"^\s*(\d+)", n)
            return m.group(1) if m else None

        try:
            dist = float(inputs.get("distance") or 0.0)
        except (TypeError, ValueError):
            dist = 0.0

        in_name = inputs.get("input_name", "") or ""
        mt_name = inputs.get("match_name", "") or ""
        in_addr = inputs.get("input_address", "") or ""
        mt_addr = inputs.get("match_address", "") or ""

        n1 = normalize_name(in_name)
        n2 = normalize_name(mt_name)
        a1 = normalize_address(in_addr)
        a2 = normalize_address(mt_addr)

        name_ratio = ratio(n1, n2)
        addr_ratio = ratio(a1, a2)
        name_jacc = jaccard(token_set(n1), token_set(n2))
        addr_jacc = jaccard(token_set(a1), token_set(a2))

        h1 = extract_house_number(in_addr)
        h2 = extract_house_number(mt_addr)
        same_house = (h1 is not None and h1 == h2)
        diff_house = (h1 is not None and h2 is not None and h1 != h2)

        # ---------------- Deterministic decisions ----------------

        # 1. Very far apart -> definitely not same place
        if dist > 500:
            return dspy.Prediction(is_same=False)

        # 2. Far apart with different house numbers -> not same
        if dist > 150 and diff_house:
            return dspy.Prediction(is_same=False)

        # 3. Far apart and names are clearly different -> not same
        #    (e.g. same street/venue address but different tenants/sections)
        if dist > 150 and name_ratio < 0.6 and name_jacc < 0.5:
            return dspy.Prediction(is_same=False)

        # 4. Same house number + very similar names -> same place
        if same_house and (name_ratio >= 0.75 or name_jacc >= 0.5):
            return dspy.Prediction(is_same=True)

        # 5. Identical normalized addresses + close + strong name similarity -> same
        if a1 == a2 and a1 != "" and dist < 100 and (name_ratio >= 0.7 or name_jacc >= 0.5):
            return dspy.Prediction(is_same=True)

        # 6. Very close and identical normalized names -> same
        if dist < 50 and n1 == n2 and n1 != "":
            return dspy.Prediction(is_same=True)

        # 7. Different house numbers + not-super-close + weak name match -> not same
        if diff_house and dist > 50 and name_ratio < 0.7:
            return dspy.Prediction(is_same=False)

        # 8. Names clearly different AND addresses clearly different -> not same
        if name_ratio < 0.4 and addr_ratio < 0.4:
            return dspy.Prediction(is_same=False)

        # 9. Very far apart, even with matching house numbers, if names differ a lot
        if dist > 300 and name_ratio < 0.7 and name_jacc < 0.6:
            return dspy.Prediction(is_same=False)

        # Ambiguous — LLM fallback
        result = self.predict(
            input_name=in_name,
            input_address=in_addr,
            match_name=mt_name,
            match_address=mt_addr,
            distance=dist,
        )
        return dspy.Prediction(is_same=bool(result.is_same))
